# Let me verify the encoding is correct by testing a simpler case
from pysat.solvers import Glucose3
from pysat.card import *
import itertools

n = 10

edge_to_var = {}
var_to_edge = {}
var_idx = 0
for i in range(n):
    for j in range(i+1, n):
        edge_to_var[(i, j)] = var_idx
        var_to_edge[var_idx] = (i, j)
        var_idx += 1

solver = Glucose3()

# Degree between 2 and 4 for 10 vertices
for v in range(n):
    edge_vars = []
    for u in range(v):
        edge_vars.append(edge_to_var[(u, v)] + 1)
    for w in range(v+1, n):
        edge_vars.append(edge_to_var[(v, w)] + 1)

    cnf_atleast = CardEnc.atleast(lits=edge_vars, bound=2, encoding=EncType.seqcounter)
    for clause in cnf_atleast.clauses:
        solver.add_clause(clause)
    cnf_atmost = CardEnc.atmost(lits=edge_vars, bound=4, encoding=EncType.seqcounter)
    for clause in cnf_atmost.clauses:
        solver.add_clause(clause)

# No triangles
for a, b, c in itertools.combinations(range(n), 3):
    e1 = edge_to_var[(min(a,b), max(a,b))] + 1
    e2 = edge_to_var[(min(b,c), max(b,c))] + 1
    e3 = edge_to_var[(min(a,c), max(a,c))] + 1
    solver.add_clause([-e1, -e2, -e3])

if solver.solve():
    model = solver.get_model()
    edge_list = []
    for var in model:
        if var > 0:
            edge = var_to_edge[var - 1]
            edge_list.append(edge)
    print(f"Found solution with {len(edge_list)} edges")
    print("Edges:", edge_list)
else:
    print("No solution")

